import{_ as a,o,c as r,a2 as e}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 3 章 我的工作方式：文件、命令与工具（易懂版）","description":"","frontmatter":{},"headers":[],"relativePath":"easy/第3章 我的工作方式：文件、命令与工具（易懂版）.md","filePath":"easy/第3章 我的工作方式：文件、命令与工具（易懂版）.md"}'),l={name:"easy/第3章 我的工作方式：文件、命令与工具（易懂版）.md"};function n(s,t,i,d,h,c){return o(),r("div",null,[...t[0]||(t[0]=[e('<h1 id="第-3-章-我的工作方式-文件、命令与工具-易懂版" tabindex="-1">第 3 章 我的工作方式：文件、命令与工具（易懂版） <a class="header-anchor" href="#第-3-章-我的工作方式-文件、命令与工具-易懂版" aria-label="Permalink to &quot;第 3 章 我的工作方式：文件、命令与工具（易懂版）&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">📖 想读完整版？</p><p>这页是<strong>易懂版</strong>，用大白话讲重点。想系统学习，请读 [第 3 章 我的工作方式：文件、命令与工具（完整版）](../../bluebook/第一篇 使用手册：先把我用起来/第 3 章 我的工作方式：文件、命令与工具.md)。</p></div><h2 id="这章讲什么-一句话" tabindex="-1">这章讲什么（一句话） <a class="header-anchor" href="#这章讲什么-一句话" aria-label="Permalink to &quot;这章讲什么（一句话）&quot;">​</a></h2><p><strong>我在你电脑里是怎么干活的——用什么、碰什么、守什么规矩。</strong></p><h2 id="先打个比方" tabindex="-1">先打个比方 <a class="header-anchor" href="#先打个比方" aria-label="Permalink to &quot;先打个比方&quot;">​</a></h2><p>我的&quot;工位&quot;就是你的<strong>工作区目录</strong>（一个文件夹）。就像新同事入职时，公司给他一把抽屉钥匙——<strong>我只能开你给我的那个抽屉</strong>，不是整栋楼。</p><h2 id="我的三样工具" tabindex="-1">我的三样工具 <a class="header-anchor" href="#我的三样工具" aria-label="Permalink to &quot;我的三样工具&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工具</th><th>干嘛用</th><th>生活比方</th></tr></thead><tbody><tr><td><strong>文件读写</strong></td><td>看你的文档、改你的文档、新建文档</td><td>打开文件柜，翻找、改写、归档</td></tr><tr><td><strong>命令执行</strong></td><td>跑程序、批量处理、查状态</td><td>有台小电脑，你发话我就按</td></tr><tr><td><strong>专用工具</strong></td><td>搜索、读网页、调 Skill、查计划</td><td>工具箱里的专业家伙什</td></tr></tbody></table><h2 id="核心就-3-件事" tabindex="-1">核心就 3 件事 <a class="header-anchor" href="#核心就-3-件事" aria-label="Permalink to &quot;核心就 3 件事&quot;">​</a></h2><ol><li><strong>干活有固定目录</strong>：我默认在你给的工作区里行动，不会乱翻整个电脑。</li><li><strong>所有动作都可追溯</strong>：我改了哪个文件、跑了哪条命令，你都能看到记录。</li><li><strong>重要操作先问你</strong>：删东西、覆盖文件、发东西到外面——这类&quot;有风险&quot;的动作，我会先跟你确认。</li></ol><h2 id="三条安全规则-记牢" tabindex="-1">三条安全规则（记牢） <a class="header-anchor" href="#三条安全规则-记牢" aria-label="Permalink to &quot;三条安全规则（记牢）&quot;">​</a></h2><ul><li>🚫 <strong>不碰你工作区之外的东西</strong>——除非你明确授权；</li><li>🚫 <strong>不偷偷删改</strong>——破坏性操作先问你；</li><li>🚫 <strong>不上传机密</strong>——重要隐私文件，别让我往外发。</li></ul><h2 id="上手小例子" tabindex="-1">上手小例子 <a class="header-anchor" href="#上手小例子" aria-label="Permalink to &quot;上手小例子&quot;">​</a></h2><blockquote><p><strong>指令</strong>：&quot;把 <code>素材</code> 文件夹里所有 <code>.txt</code> 文件合并成一个 <code>合集.txt</code>，放在工作区根目录。&quot;</p><p><strong>你会看到</strong>：我列出找到的文件 → 告诉你我会怎么合并 → 执行 → 给你看结果文件。</p></blockquote><h2 id="别踩的坑" tabindex="-1">别踩的坑 <a class="header-anchor" href="#别踩的坑" aria-label="Permalink to &quot;别踩的坑&quot;">​</a></h2><ul><li>❌ 以为我能看到你整个电脑——<strong>我只在你给的工作区里干活</strong>；</li><li>❌ 不看我干了啥——执行记录要看一眼，防止意外改动；</li><li>❌ 重要文件不备份——让我大改之前，先留个副本。</li></ul><h2 id="一句话总结" tabindex="-1">一句话总结 <a class="header-anchor" href="#一句话总结" aria-label="Permalink to &quot;一句话总结&quot;">​</a></h2><p><strong>我有三样工具（文件/命令/工具），在你给的工作区里干活，守三条安全规矩。</strong></p><h2 id="一分钟测试" tabindex="-1">一分钟测试 <a class="header-anchor" href="#一分钟测试" aria-label="Permalink to &quot;一分钟测试&quot;">​</a></h2><p>下次让我干活前，问自己：<strong>&quot;这个文件在不在工作区里？要不要先备份？&quot;</strong> 两个问题答完再发指令。</p><p>👉 [下一章：快速完成第一个真实任务（易懂版）](第4章 快速完成第一个真实任务（易懂版）.md)</p>',21)])])}const g=a(l,[["render",n]]);export{u as __pageData,g as default};
